#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; string s;
    cin>>n>>s;
    int cnt=0;
    for(char c='z';c>='b';c--){
        bool changed=true;
        while(changed){
            changed=false;
            for(int i=0;i<(int)s.size();i++){
                if(s[i]!=c) continue;
                bool ok=false;
                if(i>0 && s[i-1]==c-1) ok=true;
                if(i+1<(int)s.size() && s[i+1]==c-1) ok=true;
                if(ok){
                    s.erase(s.begin()+i);
                    cnt++;
                    changed=true;
                    break;
                }
            }
        }
    }
    cout<<cnt<<endl;
}
